import {normalize} from './core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function openConnectedInventory({session,modal,toast,actor='Teléfono vinculado',onBack}){
const $=s=>document.querySelector(s);let snapshot,query='',busy=false,interval,viewToken=0;
function list(){
viewToken++;
modal('<span class="eyebrow">PANTALLA PRINCIPAL</span><h2>Inventario conectado</h2><p id="remoteConnectionStatus" role="status">Consultando existencias…</p><div class="toolbar"><input id="remoteSearch" aria-label="Buscar en el inventario conectado" placeholder="Nombre, código, marca o ubicación"><button type="button" id="remoteRefresh">Actualizar</button></div><div id="remoteItems" class="remote-items"></div><p class="small">Los cambios se guardan en la pantalla principal. Esta vista no reemplaza el inventario local del teléfono ni trabaja sin conexión.</p><button type="button" id="backToScanner">Volver al escáner</button>');$('#backToScanner').onclick=()=>{clearInterval(interval);onBack()};$('#remoteSearch').value=query;$('#remoteSearch').oninput=e=>{query=e.target.value;draw()};$('#remoteRefresh').onclick=refresh;draw();refresh();interval=setInterval(()=>{if(!$('#remoteItems')||!$('#modal').open){clearInterval(interval);return}if(!session.connected){$('#remoteConnectionStatus').textContent='Sin conexión. Las cantidades mostradas pueden estar desactualizadas.';draw();return}refresh()},5000);
}
function draw(){const node=$('#remoteItems');if(!node)return;if(!snapshot){node.innerHTML='<div class="empty">Esperando la pantalla principal…</div>';return}const products=snapshot.products.filter(p=>normalize([p.name,p.code,p.brand,p.spec,p.shelf,p.level,p.box].join(' ')).includes(normalize(query)));node.innerHTML=products.map(p=>`<button type="button" class="remote-product" data-remote-code="${esc(p.code)}" ${session.connected?'':'disabled'}><span><b>${esc(p.name)}</b><small>${esc(p.code)} · ${esc(p.brand)}<br>${esc([p.shelf,p.level,p.box].filter(Boolean).join(' / ')||'Sin ubicación')}</small></span><strong class="${p.qty<=p.min?'low-text':''}">${esc(p.qty)}<small>unidades</small></strong></button>`).join('')||'<div class="empty">No hay coincidencias.</div>';node.querySelectorAll('[data-remote-code]').forEach(button=>button.onclick=()=>movement(snapshot.products.find(p=>p.code===button.dataset.remoteCode)))}
async function refresh(){if(busy||!$('#remoteItems'))return;busy=true;const token=viewToken,button=$('#remoteRefresh');button.disabled=true;try{const result=await session.inventory();if(token!==viewToken||!$('#remoteItems')||!$('#modal').open)return;snapshot=result;$('#remoteConnectionStatus').textContent=(snapshot.environment==='test'?'PRUEBAS':'INVENTARIO REAL')+' · '+snapshot.products.length+' de '+snapshot.total+' productos · Actualizado '+new Date(snapshot.at).toLocaleTimeString('es-SV');draw()}catch(e){if($('#remoteConnectionStatus'))$('#remoteConnectionStatus').textContent=e.message}finally{busy=false;if(button.isConnected)button.disabled=false}}
function movement(p){if(!p||!session.connected)return;clearInterval(interval);viewToken++;let saving=false;const environment=snapshot.environment,requestId=crypto.randomUUID();modal(`<span class="badge">${environment==='test'?'PRUEBAS':'REAL'} · CONECTADO</span><h2>${esc(p.name)}</h2><p>${esc(p.code)} · Disponible en principal: <b>${esc(p.qty)}</b></p><form id="remoteMove"><label>Operación<select name="type"><option value="out">Salida</option><option value="in">Entrada</option><option value="count">Conteo físico</option></select></label><label>Cantidad <span id="remoteAmountHint">a retirar</span><input name="amount" type="number" inputmode="numeric" min="1" step="1" required value="1"></label><div id="remoteDifference" class="movement-preview"></div><label>Motivo / referencia<input name="note" maxlength="180" value="Trabajo de taller"></label><label>Responsable<input name="actor" maxlength="50" required value="${esc(actor)}"></label><button id="remoteConfirm" class="primary">Confirmar en pantalla principal</button><p id="remoteMoveStatus" role="status"></p></form><button type="button" id="remoteBackList">Volver al inventario</button>`);const f=$('#remoteMove'),type=f.elements.namedItem('type'),amount=f.elements.namedItem('amount'),note=f.elements.namedItem('note');function diff(){const count=type.value==='count',n=Number(amount.value),after=count?n:p.qty+(type.value==='in'?n:-n);amount.min=count?'0':'1';note.required=count;$('#remoteAmountHint').textContent=count?'total contado':type.value==='in'?'a agregar':'a retirar';$('#remoteDifference').textContent=p.qty+' → '+after+' unidades';$('#remoteConfirm').disabled=!session.connected||!Number.isSafeInteger(n)||n<(count?0:1)||after<0;};type.onchange=()=>{note.value=type.value==='count'?'':type.value==='in'?'Compra / recepción':'Trabajo de taller';diff()};f.oninput=diff;diff();$('#remoteBackList').onclick=list;
f.onsubmit=async e=>{e.preventDefault();if(saving)return;if(type.value==='count'&&!note.value.trim()){toast('Escribe el motivo del conteo.');return}saving=true;const button=$('#remoteConfirm'),status=$('#remoteMoveStatus');button.disabled=true;status.textContent='Esperando guardado en la pantalla principal…';try{snapshot=await session.changeInventory({requestId,environment,code:p.code,type:type.value,amount:Number(amount.value),note:note.value.trim(),actor:f.elements.namedItem('actor').value.trim(),expectedQty:p.qty});if(status.isConnected){toast('Movimiento guardado en la pantalla principal');list()}}catch(error){if(status.isConnected)status.textContent=error.message}finally{saving=false;if(button.isConnected)button.disabled=!session.connected}};
}
list();
}
